#!/usr/bin/env bash
# core.bash - ESSENTIAL (< 10ms)
# Auto-generated by wayu build

# === Environment (from wayu.toml [env]) ===
export EDITOR="nvim"
export GREETING="hello world"
export PROJECTS="$HOME/projects"

# === PATH (from wayu.toml [paths], live-synced at each prompt) ===
_wayu_paths_apply() {
  local first=0 d e prev="" IFS=':' nl='
'
  [ -n "${_WAYU_PATHS_SIG-}" ] || first=1
  _WAYU_PATHS_SIG="# wayu-paths $1"
  shift
  local want=":" old=":${_WAYU_PATHS_MANAGED-}:" now=":$PATH:" managed=":" keep=":" out
  local -a cur ks
  for d in "$@"; do
    case "$d" in ""|*:*|*"$nl"*) continue ;; esac
    [ -d "$d" ] || continue
    case "$want" in *":$d:"*) continue ;; esac
    want="$want$d:"
    case "$old" in
      *":$d:"*) managed="$managed$d:" ;;
      *) case "$now" in *":$d:"*) ;; *) managed="$managed$d:" ;; esac ;;
    esac
  done
  read -r -a cur <<< "$PATH"
  for d in ${cur[@]+"${cur[@]}"}; do
    [ -n "$d" ] || continue
    case "$old" in *":$d:"*) case "$want" in *":$d:"*) ;; *) continue ;; esac ;; esac
    if [ "$first" -eq 1 ]; then case "$want" in *":$d:"*) continue ;; esac; fi
    case "$keep" in *":$d:"*) continue ;; esac
    keep="$keep$d:"
  done
  if [ "$first" -eq 1 ]; then
    keep="$want${keep#:}"
  else
    read -r -a cur <<< "${want#:}"
    for d in ${cur[@]+"${cur[@]}"}; do
      case "$keep" in
        *":$d:"*) ;;
        *)
          if [ -z "$prev" ]; then
            keep=":$d$keep"
          else
            out=":"
            read -r -a ks <<< "${keep#:}"
            for e in ${ks[@]+"${ks[@]}"}; do
              out="$out$e:"
              [ "$e" = "$prev" ] && out="$out$d:"
            done
            keep="$out"
          fi ;;
      esac
      prev="$d"
    done
  fi
  keep="${keep#:}"
  managed="${managed#:}"
  PATH="${keep%:}"
  _WAYU_PATHS_MANAGED="${managed%:}"
  export PATH _WAYU_PATHS_MANAGED
}
_wayu_paths_sync() {
  local s=$? l
  if [ "${_WAYU_PATHS_REGEN-1}" = 1 ] && [ -n "${_WAYU_TOML_FILE-}" ] && [ "$_WAYU_TOML_FILE" -nt "$_WAYU_PATHS_FILE" ]; then
    command "${_WAYU_BIN:-wayu}" build </dev/null >/dev/null 2>&1
    [ "$_WAYU_TOML_FILE" -nt "$_WAYU_PATHS_FILE" ] && _WAYU_PATHS_REGEN=0
  fi
  { read -r l < "$_WAYU_PATHS_FILE"; } 2>/dev/null || return $s
  [ "$l" = "${_WAYU_PATHS_SIG-}" ] || . "$_WAYU_PATHS_FILE"
  return $s
}
case ";${PROMPT_COMMAND-};" in
  *";_wayu_paths_sync;"*) ;;
  *) PROMPT_COMMAND="_wayu_paths_sync${PROMPT_COMMAND:+;$PROMPT_COMMAND}" ;;
esac
_WAYU_PATHS_FILE="@HOME@/.config/wayu/path_sync.bash"
_WAYU_BIN="@WAYU_BIN@"
_WAYU_TOML_FILE="@HOME@/.config/wayu/wayu.toml"
if [ -f "$_WAYU_PATHS_FILE" ]; then . "$_WAYU_PATHS_FILE"; fi
# Deduplicate PATH (preserve order, remove duplicates)
_wayu_dedup_path() {
  local IFS=':' _wayu_p _wayu_new=""
  for _wayu_p in $PATH; do
    [ -n "$_wayu_p" ] || continue
    case ":$_wayu_new:" in *":$_wayu_p:"*) ;; *) _wayu_new="${_wayu_new:+$_wayu_new:}$_wayu_p" ;; esac
  done
  export PATH="$_wayu_new"
}
_wayu_dedup_path
unset -f _wayu_dedup_path

# === Aliases (from wayu.toml [aliases]) ===
alias gs='git status --short'
alias ll='ls -la'
alias q='echo "it'\''s quoted"'

# === Completions ===
if [ -d "@HOME@/.config/wayu/completions" ]; then for f in "@HOME@/.config/wayu/completions"/*.bash-completion; do if [ -f "$f" ]; then source "$f"; fi; done; fi

# === Functions ===
if [ -d "@HOME@/.config/wayu/functions" ]; then for f in "@HOME@/.config/wayu/functions"/*; do if [ -f "$f" ]; then source "$f"; fi; done; fi

# === Load helpers ===
source "@HOME@/.config/wayu/helpers.bash" 2>/dev/null || true

# === Plugins ===
if [ -f "@HOME@/.config/wayu/plugins.bash" ]; then source "@HOME@/.config/wayu/plugins.bash"; fi

# === Lazy init (tools, extra config) ===
source "@HOME@/.config/wayu/lazy.bash"

